(1, 'http://e-hms-saas-filament.test/uploads/14/07.png', 'http://e-hms-saas-filament.test/uploads/15/card_img_url_one.png', 'http://e-hms-saas-filament.test/uploads/16/card_img_url_two.png', 'http://e-hms-saas-filament.test/uploads/17/card_img_url_three.png', 'http://e-hms-saas-filament.test/uploads/18/card_imf_url_four.png', 234, 455, 365, 528, 'Services', 'Team Members', 'Happy Patients', 'Tonic Research', '2025-06-21 00:42:23', '2025-06-21 00:42:23');
INSERT INTO `section_fours` (`id`, `text_main`, `text_secondary`, `img_url_one`, `img_url_two`, `img_url_three`, `img_url_four`, `img_url_five`, `img_url_six`, `card_text_one`, `card_text_two`, `card_text_three`, `card_text_four`, `card_text_five`, `card_text_six`, `card_text_one_secondary`, `card_text_two_secondary`, `card_text_three_secondary`, `card_text_four_secondary`, `card_text_five_secondary`, `card_text_six_secondary`, `created_at`, `updated_at`) VALUES
(1, 'Grow Your Hospital', 'We Help To Grow Your Hospital Beyond Your Expectation', 'http://e-hms-saas-filament.test/uploads/8/bulit_seo.png', 'http://e-hms-saas-filament.test/uploads/9/hospital_profile.png', 'http://e-hms-saas-filament.test/uploads/10/online_appointment.png', 'http://e-hms-saas-filament.test/uploads/11/articles.png', 'http://e-hms-saas-filament.test/uploads/12/easy_to_use.png', 'http://e-hms-saas-filament.test/uploads/13/support.jpeg', 'Built SEO', 'Hospital Profile', 'Online Appointment', 'Articles', 'Easy to Use', '24*7 Support', 'SEO Brings Higher patient retention Rates which will Results into Higher Conversion Rate.', 'More than 80% of people searching for medical professionals make their selection from HMS.', 'Provide comfort to your patients in this pandemic situation to book online appointments.', 'Keep updated with latest techniques/knowledge/research to build a professional network.', 'Top quality Software with all Features easy to use and easily accessible.', 'Any time we are here to help you.', '2025-06-21 00:42:23', '2025-06-21 00:42:23');
INSERT INTO `section_ones` (`id`, `text_main`, `text_secondary`, `img_url`, `created_at`, `updated_at`) VALUES
(1, 'Manage Hospital Never Before', 'A Next Level Evolution In Healthcare IT, Web Based EMR, Revenue Cycle Management Solution, Designed To Meet The Opportunities.', 'http://e-hms-saas-filament.test/uploads/3/section_one.png', '2025-06-21 00:42:23', '2025-06-21 00:42:23');
INSERT INTO `section_threes` (`id`, `text_main`, `text_secondary`, `img_url`, `text_one`, `text_two`, `text_three`, `text_four`, `text_five`, `created_at`, `updated_at`) VALUES
(1, 'Why Hospital SAAS?', 'We have implemented, Hospital SAAS for our patient\'s registration, appointment scheduling, inpatient management, ICU management, OT management, pharmacy.', 'http://e-hms-saas-filament.test/uploads/7/section_three_sass.png', 'Fully Secure', 'Easy To Use', 'Regular Updates', '24*7 Support', NULL, '2025-06-21 00:42:23', '2025-06-21 00:42:23');
INSERT INTO `section_twos` (`id`, `text_main`, `text_secondary`, `card_one_image`, `card_one_text`, `card_one_text_secondary`, `card_two_image`, `card_two_text`, `card_two_text_secondary`, `card_third_image`, `card_third_text`, `card_third_text_secondary`, `created_at`, `updated_at`) VALUES
(1, 'Protect Your Health', 'Our medical clinic provides quality care for the entire family while maintaining a personable atmosphere best services.', 'http://e-hms-saas-filament.test/uploads/4/appointment_schedule.png', 'Schedule Appointment', 'Makes it Easy for patients to Book Appointment online from anywhere &amp; anytime.', 'http://e-hms-saas-filament.test/uploads/5/ipd_manage.png', 'OPD Management', 'Easily Manage Appointments with one.', 'http://e-hms-saas-filament.test/uploads/6/opd_manage.png', 'IPD Management', 'This module of hospital management system is designed to manage all Inpatient department', '2025-06-21 00:42:23', '2025-06-21 00:42:23');
